review_comment:
The cache key only includes `app_dir`, but the function also depends on the user's home directory via `os.path.expanduser("~")` at line 291. If the HOME environment variable changes during process lifetime (possible in containerized environments or when running tests), the cache will return stale results.

This can be fixed by either:
```python
@lru_cache(maxsize=1)
def _detect_installed_skills_cached(app_dir: str | None, home: str) -> tuple[str, ...]:
    # Use passed home instead of os.path.expanduser("~")
```

Or remove caching on the internal function and cache at the wrapper level:
```python
def _detect_installed_skills(app_dir: str | None) -> list[str]:
    home = os.path.expanduser("~")
    return list(_detect_installed_skills_impl(app_dir, home))

@lru_cache(maxsize=8)  # Cache multiple app_dir + home combinations
def _detect_installed_skills_impl(app_dir: str | None, home: str) -> tuple[str, ...]:
    # ... existing logic ...
```
```suggestion

@lru_cache(maxsize=8)
def _detect_installed_skills_cached(app_dir: str | None, home: str) -> tuple[str, ...]:
    try:
        app = os.path.abspath(app_dir) if app_dir else os.getcwd()
        repo = _find_git_root(app)

        roots: dict[str, str] = {"home": home, "app": app}
        # Only include ``repo`` when it's distinct from ``app`` to avoid
        # double-counting the common case where the app script lives at the
        # repo root.
        if repo is not None and os.path.abspath(repo) != app:
            roots["repo"] = repo

        tokens: set[str] = set()
        for location, root in roots.items():
            for harness, project_dir, home_dirs in _HARNESSES:
                harness_dirs = home_dirs if location == "home" else (project_dir,)
                for harness_dir in harness_dirs:
                    for skill in _STREAMLIT_SKILL_NAMES:
                        marker = os.path.join(
                            root, harness_dir, skill, _SKILL_MARKER_FILENAME
                        )
                        if os.path.isfile(marker):
                            tokens.add(f"{location}:{harness}:{skill}")
        return tuple(sorted(tokens))
    except Exception as ex:  # pragma: no cover - defensive
        _LOGGER.debug("Failed to detect installed Streamlit skills", exc_info=ex)
        return ()

```


