This autouse fixture will run for every test in `metrics_util_test.py`, even though it’s only needed for the new skill-detection tests. Consider making it non-autouse and explicitly depending on it in the relevant tests, or scoping the cache reset more narrowly to reduce unintended coupling/overhead across this large module.
```suggestion
def _needs_skills_cache_reset(request: pytest.FixtureRequest) -> bool:
    """Return whether the current test exercises skill-detection caching."""
    test_name = request.node.name
    return "skill" in test_name


@pytest.fixture(autouse=True)
def _clear_skills_cache(request: pytest.FixtureRequest) -> Iterator[None]:
    """Reset the skill-detection cache only for tests that use it."""
    if not _needs_skills_cache_reset(request):
        yield
        return
```

The `_downcast_type()` function only handles top-level `large_list` types but doesn't recursively handle nested complex types like structs or maps that may contain `large_list` fields. For example, a struct field containing a `large_list` won't be downcast, causing Arrow JS compatibility issues.

```python
def _downcast_type(arrow_type: pa.DataType) -> pa.DataType:
    if isinstance(arrow_type, pa.LargeListType):
        return pa.list_(_downcast_type(arrow_type.value_type))
    # Missing: handle StructType
    if isinstance(arrow_type, pa.StructType):
        return pa.struct([pa.field(f.name, _downcast_type(f.type)) for f in arrow_type])
    # Missing: handle MapType
    if isinstance(arrow_type, pa.MapType):
        return pa.map_(_downcast_type(arrow_type.key_type), _downcast_type(arrow_type.item_type))
    return arrow_type
```
```suggestion

def _downcast_large_list_schema(schema: pa.Schema) -> pa.Schema:
    """Build a new schema with large_list types downcast to list."""
    import pyarrow as pa

    def _downcast_type(arrow_type: pa.DataType) -> pa.DataType:
        if isinstance(arrow_type, pa.LargeListType):
            return pa.list_(_downcast_type(arrow_type.value_type))
        if isinstance(arrow_type, pa.StructType):
            return pa.struct(
                [pa.field(f.name, _downcast_type(f.type)) for f in arrow_type]
            )
        if isinstance(arrow_type, pa.MapType):
            return pa.map_(
                _downcast_type(arrow_type.key_type),
                _downcast_type(arrow_type.item_type),
            )
        return arrow_type

    new_fields = [pa.field(f.name, _downcast_type(f.type)) for f in schema]
    return pa.schema(new_fields)

```


