review_comment:
The cache does not override all methods that remove items. Missing overrides for `__delitem__`, `pop`, `clear`, and `__setitem__` (for value replacement) will cause resource leaks. When users call `del cache[key]`, `cache.pop(key)`, `cache.clear()`, or replace existing values via `cache[key] = new_value`, the `on_release` hook will not be called.

Fix by adding these overrides:

```python
@override
def __delitem__(self, key: K) -> None:
    value = self[key]
    super().__delitem__(key)
    self._on_release(value)

@override
def pop(self, key: K, *args) -> V:  # type: ignore[override]
    value = super().pop(key, *args)
    if key in self or len(args) == 0:  # Only release if item was in cache
        self._on_release(value)
    return value

@override
def clear(self) -> None:
    for value in self.values():
        self._on_release(value)
    super().clear()

@override
def __setitem__(self, key: K, value: V) -> None:
    if key in self:
        old_value = self[key]
        super().__setitem__(key, value)
        self._on_release(old_value)
    else:
        super().__setitem__(key, value)
```
```suggestion
class TTLCleanupCache(TTLCache[K, V]):
    """A TTLCache that supports hooks called when items are released."""

    def __init__(
        self,
        maxsize: float,
        ttl: float,
        timer: Callable[[], float],
        on_release: OnRelease,
    ) -> None:
        """Create a cache with the given size, TTL, and release hook.

        Parameters
        ----------
        maxsize : float
            The maximum number of elements this cache should hold.
        ttl : float
            The amount of time a cache entry should remain valid, in seconds.
        timer : Callable[[], float]
            The timer function to use to fetch the current time.
        on_release : OnRelease
            The function to call with cache entries when they are removed from the
            cache.
        """
        super().__init__(maxsize=maxsize, ttl=ttl, timer=timer)
        self._on_release = on_release

    @override
    def popitem(self) -> tuple[K, V]:
        key, value = super().popitem()
        self._on_release(value)
        return key, value

    @override
    def expire(self, time: float | None = None) -> list[tuple[K, V]]:
        items = super().expire(time)
        for _, value in items:
            self._on_release(value)

        return items

    @override
    def __delitem__(self, key: K) -> None:
        value = self[key]
        super().__delitem__(key)
        self._on_release(value)

    @override
    def pop(self, key: K, *args) -> V:  # type: ignore[override]
        value = super().pop(key, *args)
        if key in self or len(args) == 0:  # Only release if item was in cache
            self._on_release(value)
        return value

    @override
    def clear(self) -> None:
        for value in self.values():
            self._on_release(value)
        super().clear()

    @override
    def __setitem__(self, key: K, value: V) -> None:
        if key in self:
            old_value = self[key]
            super().__setitem__(key, value)
            self._on_release(old_value)
        else:
            super().__setitem__(key, value)
```


